const I18N = {
  lang: "fr",
  t(k, vars) {
    let v = (DICT[this.lang] && DICT[this.lang][k]) ?? DICT.fr[k] ?? k;
    if (vars && typeof v === "string") for (const [a, b] of Object.entries(vars)) v = v.replace(`{${a}}`, b);
    return v;
  },
  apply() {
    const d = DICT[this.lang];
    document.documentElement.lang = this.lang; document.documentElement.dir = d._dir;
    document.querySelectorAll("[data-i18n]").forEach(el => { el.textContent = this.t(el.dataset.i18n); });
    document.querySelectorAll("[data-i18n-ph]").forEach(el => { el.placeholder = this.t(el.dataset.i18nPh); });
    document.querySelectorAll("[data-i18n-aria]").forEach(el => { el.setAttribute("aria-label", this.t(el.dataset.i18nAria)); });
    document.querySelectorAll("[data-i18n-list]").forEach(el => {
      const items = this.t(el.dataset.i18nList), tag = el.dataset.tag || "li";
      el.innerHTML = items.map(x => `<${tag}>${x}</${tag}>`).join("");
    });
    document.querySelectorAll("[data-i18n-options]").forEach(el => {
      const items = this.t(el.dataset.i18nOptions), cur = el.selectedIndex;
      el.innerHTML = items.map((x, i) => `<option value="${i}">${x}</option>`).join(""); if (cur > 0) el.selectedIndex = cur;
    });
    document.querySelectorAll(".lang button").forEach(b => b.classList.toggle("on", b.dataset.lang === this.lang));
    document.dispatchEvent(new CustomEvent("langchange", { detail: this.lang }));
  },
  set(l) { if (!DICT[l]) return; this.lang = l; try { localStorage.setItem("vr-lang", l); } catch (e) {} this.apply(); },
  init() {
    let l = new URLSearchParams(location.search).get("lang");
    if (!l) { try { l = localStorage.getItem("vr-lang"); } catch (e) {} }
    if (!l) { const n = (navigator.language || "fr").slice(0, 2); l = DICT[n] ? n : "fr"; }
    this.lang = DICT[l] ? l : "fr"; this.apply();
  }
};
window.I18N = I18N;
